-- Athena saved query (Product_B2C_Intl)
-- ID: 1b9ab1fe-9078-47ad-9a9c-a72be13e88f1
-- Name: Bus Images Dashboard Engagement - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH sl_deduped AS ( SELECT __time, CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, mri_session_id, route_id, os, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) > 2 THEN '3. DBD 2+' END AS dbd FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND channel = 'MOBILE_APP' AND os = 'iOS' AND country = 'IND' AND app_code >= 859800 AND status = 200 AND tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5, 6 ), base AS ( SELECT -- u.__time, CAST(DATE_TRUNC('day', at_timezone(u.__time, 'Asia/Kolkata')) AS DATE) AS doi, u.event_src channel, -- CASE WHEN CAST(doj_doi AS INT) <= 0 THEN '0. Same Day' -- WHEN CAST(doj_doi AS INT) = 1 THEN '1. DBD 1' -- WHEN CAST(doj_doi AS INT) = 2 THEN '2. DBD 2' -- WHEN CAST(doj_doi AS INT) = 3 THEN '3. DBD 2+' -- ELSE '' -- END AS DBD, u.route_id_train_no route_id, u.mri_session_id, MAX(CASE WHEN u.event_group = 'sl_screen_load' AND u.event_name LIKE '%sl_loaded%' THEN 1 ELSE 0 END) AS overall_sl_loaded, MAX(CASE WHEN event_group = 'ab_exp_imagesSectionLoaded' AND event_name = 'ImagesSection_loaded' THEN 1 ELSE 0 END) AS ImagesSection_loaded, MAX(CASE WHEN event_group = 'ab_exp_imagesGalleryLoaded' AND event_name = 'ImagesGalleryLoaded' THEN 1 ELSE 0 END) AS Clicked_on_Images, MAX(CASE WHEN u.event_group = 'ab_exp_busImage' AND u.event_name = 'NewBusImageLoaded' THEN 1 ELSE 0 END) AS SL_Load_with_New_Bus_Images FROM "user_interaction"."ui_ux_events" u WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND event_src IN ('iOS') -- AND event_name IN ('ImagesSection_loaded') AND event_group IN ('sl_screen_load', 'ab_exp_busImage', 'ab_exp_imagesGalleryLoaded', 'ab_exp_imagesSectionLoaded') AND (event_name IN ('NewBusImageLoaded', 'ImagesSection_loaded', 'ImagesGalleryLoaded') OR event_name LIKE '%sl_loaded%') GROUP BY 1, 2, 3, 4 ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- * sl.doi, sl.os channel, COUNT(DISTINCT CASE WHEN b.overall_sl_loaded = 1 THEN sl.mri_session_id END) AS overall_sl_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 THEN sl.mri_session_id END) AS SL_Load_with_New_Bus_Images, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 THEN sl.mri_session_id END) AS SL_ImagesSection_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 AND Clicked_on_Images = 1 THEN sl.mri_session_id END) AS SL_Clicked_on_Images_New, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 AND Clicked_on_Images = 1 THEN sl.mri_session_id END) AS SL_Clicked_on_Images_Old, COUNT(DISTINCT CASE WHEN b.overall_sl_loaded = 1 THEN mp.mri_session_id END) AS overall_CI_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 THEN mp.mri_session_id END) AS CI_Load_with_New_Bus_Images, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 THEN mp.mri_session_id END) AS CI_ImagesSection_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 AND Clicked_on_Images = 1 THEN mp.mri_session_id END) AS CI_Clicked_on_Images_New, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 AND Clicked_on_Images = 1 THEN mp.mri_session_id END) AS CI_Clicked_on_Images_Old, COUNT(DISTINCT CASE WHEN b.overall_sl_loaded = 1 THEN oi.mri_session_id END) AS overall_Pay_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 THEN oi.mri_session_id END) AS Pay_Load_with_New_Bus_Images, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 THEN oi.mri_session_id END) AS Pay_ImagesSection_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 AND Clicked_on_Images = 1 THEN oi.mri_session_id END) AS Pay_Clicked_on_Images_New, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 AND Clicked_on_Images = 1 THEN oi.mri_session_id END) AS Pay_Clicked_on_Images_Old, COUNT(DISTINCT CASE WHEN b.overall_sl_loaded = 1 THEN c.mri_session_id END) AS overall_Conf_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 THEN c.mri_session_id END) AS Conf_Load_with_New_Bus_Images, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 THEN c.mri_session_id END) AS Conf_ImagesSection_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 AND Clicked_on_Images = 1 THEN c.mri_session_id END) AS Conf_Clicked_on_Images_New, COUNT(DISTINCT CASE WHEN b.ImagesSection_loaded = 1 AND Clicked_on_Images = 1 THEN c.mri_session_id END) AS Conf_Clicked_on_Images_Old FROM base b LEFT JOIN sl_deduped sl ON sl.mri_session_id = b.mri_session_id AND sl.route_id = CAST(b.route_id AS BIGINT) LEFT JOIN mpax_deduped mp ON mp.mri_session_id = b.mri_session_id AND mp.route_id = CAST(b.route_id AS BIGINT) LEFT JOIN orderinfo_deduped oi ON oi.mri_session_id = b.mri_session_id AND oi.route_id = CAST(b.route_id AS BIGINT) LEFT JOIN confirm_deduped c ON c.mri_session_id = b.mri_session_id AND c.route_id = CAST(b.route_id AS BIGINT) -- LIMIT 100 GROUP BY 1, 2 ORDER BY 1, 2 -- LIMIT 100
